window.EDU_UNITS = [{"id":"g1-int-2-06","catalogUnit":"g1-통합교과-2학기-6","grade":1,"subject":"통합교과","unitTitle":"6. 약속","flow":"1~8차시는 학교와 동네를 둘러보며 다니기 불편한 곳을 찾고, 그곳이 특히 누구에게 불편할지 다른 사람의 자리에서 생각합니다. 9~16차시는 찾은 곳을 고칠 방법을 그리고, 어린이가 바로 할 수 있는 일과 어른께 부탁할 일을 나누어 우리 반 약속으로 실천합니다. 17~24차시는 고친 뒤 무엇이 달라졌는지 견주고, 지키지 못한 날은 다시 하며, 더 고칠 곳을 선생님께 알리는 습관을 기릅니다. 25~40차시는 표현 재료와 용구로 넘어가 색연필·크레파스·종이·풀·가위를 견주고 안전하게 쓰는 약속을 익힌 뒤, 오리고 붙이고 소리 내어 작품을 만듭니다. 41~48차시는 쓴 재료를 제자리에 정리하고 내 작품을 돌아보아 다시 만들며, 마지막 시간에 단원 전체의 약속을 스스로 평가합니다.","lessons":[{"n":1,"id":"g1-int-2-06-01"},{"n":2,"id":"g1-int-2-06-02"},{"n":3,"id":"g1-int-2-06-03"},{"n":4,"id":"g1-int-2-06-04"},{"n":5,"id":"g1-int-2-06-05"},{"n":6,"id":"g1-int-2-06-06"},{"n":7,"id":"g1-int-2-06-07"},{"n":8,"id":"g1-int-2-06-08"},{"n":9,"id":"g1-int-2-06-09"},{"n":10,"id":"g1-int-2-06-10"},{"n":11,"id":"g1-int-2-06-11"},{"n":12,"id":"g1-int-2-06-12"},{"n":13,"id":"g1-int-2-06-13"},{"n":14,"id":"g1-int-2-06-14"},{"n":15,"id":"g1-int-2-06-15"},{"n":16,"id":"g1-int-2-06-16"},{"n":17,"id":"g1-int-2-06-17"},{"n":18,"id":"g1-int-2-06-18"},{"n":19,"id":"g1-int-2-06-19"},{"n":20,"id":"g1-int-2-06-20"},{"n":21,"id":"g1-int-2-06-21"},{"n":22,"id":"g1-int-2-06-22"},{"n":23,"id":"g1-int-2-06-23"},{"n":24,"id":"g1-int-2-06-24"},{"n":25,"id":"g1-int-2-06-25"},{"n":26,"id":"g1-int-2-06-26"},{"n":27,"id":"g1-int-2-06-27"},{"n":28,"id":"g1-int-2-06-28"},{"n":29,"id":"g1-int-2-06-29"},{"n":30,"id":"g1-int-2-06-30"},{"n":31,"id":"g1-int-2-06-31"},{"n":32,"id":"g1-int-2-06-32"},{"n":33,"id":"g1-int-2-06-33"},{"n":34,"id":"g1-int-2-06-34"},{"n":35,"id":"g1-int-2-06-35"},{"n":36,"id":"g1-int-2-06-36"},{"n":37,"id":"g1-int-2-06-37"},{"n":38,"id":"g1-int-2-06-38"},{"n":39,"id":"g1-int-2-06-39"},{"n":40,"id":"g1-int-2-06-40"},{"n":41,"id":"g1-int-2-06-41"},{"n":42,"id":"g1-int-2-06-42"},{"n":43,"id":"g1-int-2-06-43"},{"n":44,"id":"g1-int-2-06-44"},{"n":45,"id":"g1-int-2-06-45"},{"n":46,"id":"g1-int-2-06-46"},{"n":47,"id":"g1-int-2-06-47"},{"n":48,"id":"g1-int-2-06-48"}],"planned":48,"bundleSha256":"44996ba43ac86c9b332819944bd96ca5dbbde382e55da4e9624504918ed7a802"},{"id":"g2-kor-1-01","catalogUnit":"g2-국어-1학기-1","grade":2,"subject":"국어","unitTitle":"1. 만나서 반가워요!","flow":"앞의 다섯 차시는 대화에서 말차례를 다룹니다. 말차례가 무엇인지 알아보고(1), 전화·모둠·수업처럼 자리를 바꾸어 연습한 뒤(2), 바라보고 되풀이하며 듣기(3), 차례를 기다리고 넘기기(4), 스스로 돌아보기(5)로 쌓습니다. 6~10차시는 같은 듣기·말하기를 반 앞 발표로 넓혀 바른 자세와 목소리(6·7), 낱말로 준비해 문장으로 말하기(8), 겪은 일 두세 문장 발표(9), 칭찬과 고칠 점 말하기(10)로 이어집니다. 11~15차시는 말로 하던 소개를 글로 옮겨 소개할 내용 고르기(11·12), 살펴보고 차례대로 쓰기(13), 아끼는 물건 소개하고 질문받기(14), 고쳐 쓰고 단원 전체 돌아보기(15)로 마칩니다. 차시마다 교구로 먼저 가르고 고른 뒤 짝·모둠과 실제로 말하거나 써 봅니다.","lessons":[{"n":1,"id":"g2-kor-1-01-01"},{"n":2,"id":"g2-kor-1-01-02"},{"n":3,"id":"g2-kor-1-01-03"},{"n":4,"id":"g2-kor-1-01-04"},{"n":5,"id":"g2-kor-1-01-05"},{"n":6,"id":"g2-kor-1-01-06"},{"n":7,"id":"g2-kor-1-01-07"},{"n":8,"id":"g2-kor-1-01-08"},{"n":9,"id":"g2-kor-1-01-09"},{"n":10,"id":"g2-kor-1-01-10"},{"n":11,"id":"g2-kor-1-01-11"},{"n":12,"id":"g2-kor-1-01-12"},{"n":13,"id":"g2-kor-1-01-13"},{"n":14,"id":"g2-kor-1-01-14"},{"n":15,"id":"g2-kor-1-01-15"}],"planned":15,"bundleSha256":"cf21b9ec65e4422ca1c800470b5b1228bcedf09d76cc4fe444093e1f00ee06ce"},{"id":"g2-math-2-04","catalogUnit":"g2-수학-2학기-4","grade":2,"subject":"수학","unitTitle":"4. 시각과 시간","flow":"1학년 때 배운 몇 시·몇 시 30분에서 출발해, 첫 시간에 짧은바늘은 시, 긴바늘은 분을 나타내고 긴바늘의 숫자 한 칸이 5분임을 5씩 뛰어 세며 확인합니다. 2차시(기존 차시)에서 5분·1분 단위로 읽고 만든 뒤, 3·4차시에서 분이 지난 만큼 짧은바늘이 두 숫자 사이 어디에 있는지 찾고 디지털 표기와 짝지으며, \"몇 시 몇 분 전\"과 하루 일과로 생활에 옮깁니다. 5~8차시는 긴바늘 한 바퀴가 60분 = 1시간임을 알고, 걸린 시간을 시간 띠에 화살표로 나타내고 \"몇 분\"과 \"몇 시간 몇 분\"으로 바꾸어 쓴 다음, 시작·끝 시각으로 걸린 시간을 구합니다. 9~11차시는 하루 24시간(오전·오후), 1주일 7일, 달마다 다른 날수, 1년 12개월을 달력으로 확인하고, 며칠 뒤·몇 주 뒤 날짜 찾기와 알맞은 시간 단위 고르기로 단원을 정리합니다.","lessons":[{"n":1,"id":"g2-math-2-04-01"},{"n":2,"id":"g2-math-clock"},{"n":3,"id":"g2-math-2-04-03"},{"n":4,"id":"g2-math-2-04-04"},{"n":5,"id":"g2-math-2-04-05"},{"n":6,"id":"g2-math-2-04-06"},{"n":7,"id":"g2-math-2-04-07"},{"n":8,"id":"g2-math-2-04-08"},{"n":9,"id":"g2-math-2-04-09"},{"n":10,"id":"g2-math-2-04-10"},{"n":11,"id":"g2-math-2-04-11"}],"planned":11,"bundleSha256":"b3d7438ca02fb3b9ab564db9e74ab12ee75606dec561bb34c4fe6ae7b45efcf5"},{"id":"g4-art-1-01","catalogUnit":"g4-미술-1학기-1","grade":4,"subject":"미술","unitTitle":"1. 미적 체험","flow":"앞의 열두 차시는 감각으로 대상을 살피는 힘을 쌓습니다. 1~4차시는 눈·손·코·귀로 살펴 미리 알던 모습과 새로 알게 된 모습을 가르고, 친구와 다르게 본 점·만진 느낌·보는 거리에 따라 달라지는 모습을 찾습니다. 5~8차시는 위·옆·아래처럼 여러 방향에서 살펴 찾은 점을 적고 하나를 골라 크게 나타내며, 9~12차시는 살피기 전과 뒤에 달라진 생각을 말하고 다음에 살필 대상을 고릅니다. 뒤의 열한 차시는 같은 살피는 힘을 생활로 넓혀, 13~16차시에서 표지판·생활용품·무늬 속 미술이 하는 일을 찾고 근거를 댑니다. 17~20차시는 찾은 미술을 갈래로 나누어 이름을 붙이고 학교 안내 그림을 직접 꾸미며, 21~23차시는 친구의 갈래와 견주어 이름을 고치고 단원 전체를 스스로 돌아봅니다.","lessons":[{"n":1,"id":"g4-art-1-01-01"},{"n":2,"id":"g4-art-1-01-02"},{"n":3,"id":"g4-art-1-01-03"},{"n":4,"id":"g4-art-1-01-04"},{"n":5,"id":"g4-art-1-01-05"},{"n":6,"id":"g4-art-1-01-06"},{"n":7,"id":"g4-art-1-01-07"},{"n":8,"id":"g4-art-1-01-08"},{"n":9,"id":"g4-art-1-01-09"},{"n":10,"id":"g4-art-1-01-10"},{"n":11,"id":"g4-art-1-01-11"},{"n":12,"id":"g4-art-1-01-12"},{"n":13,"id":"g4-art-1-01-13"},{"n":14,"id":"g4-art-1-01-14"},{"n":15,"id":"g4-art-1-01-15"},{"n":16,"id":"g4-art-1-01-16"},{"n":17,"id":"g4-art-1-01-17"},{"n":18,"id":"g4-art-1-01-18"},{"n":19,"id":"g4-art-1-01-19"},{"n":20,"id":"g4-art-1-01-20"},{"n":21,"id":"g4-art-1-01-21"},{"n":22,"id":"g4-art-1-01-22"},{"n":23,"id":"g4-art-1-01-23"}],"planned":23,"bundleSha256":"0461628b1f25bc595c6f26066333bc131249e9bc07e9cd9837f19f25244f9d90"},{"id":"g4-mor-1-03","catalogUnit":"g4-도덕-1학기-3","grade":4,"subject":"도덕","unitTitle":"3. 배려하는 우리","flow":"배려를 사람에서 살아 있는 모든 것으로 넓히는 단원입니다. 1차시에는 동물·식물·작은 벌레를 대하는 행동 카드를 돌보는 행동과 함부로 대하는 행동으로 나누며 \"아프게 하지 않기, 필요한 것 챙기기, 살던 곳에서 살게 하기\"라는 잣대를 세웁니다. 2차시에는 직접 지은 사례(버려진 강아지, 말라 버린 화분, 잡아 온 올챙이)에서 생명이 다친 과정을 차례로 놓고 막을 수 있었던 순간과 까닭을 찾습니다. 3차시에는 그 생각을 학교 화단·연못에 붙일 짧은 알림 문구로 옮기고, 친구 문구를 배려하는 말로 함께 고칩니다. 4차시에는 학교 둘레 지도에서 생명이 위협받는 곳을 찾고 우리가 바꿀 일과 어른 도움이 필요한 일로 나눈 뒤 단원을 스스로 돌아봅니다.","lessons":[{"n":1,"id":"g4-mor-1-03-01"},{"n":2,"id":"g4-mor-1-03-02"},{"n":3,"id":"g4-mor-1-03-03"},{"n":4,"id":"g4-mor-1-03-04"}],"planned":4,"bundleSha256":"3ab1e8db9d78c463e7b599dee575ebf7c54bcc8997922894f12f937b093fb83b"},{"id":"g4-mus-1-01","catalogUnit":"g4-음악-1학기-1","grade":4,"subject":"음악","unitTitle":"1. 연주","flow":"앞의 열두 차시는 몸과 놀이로 음악을 즐깁니다: 박·센박·가락의 오르내림·세마치장단을 손뼉·무릎·손 높이로 나타내고(1~4차시), 곡의 흐름에 맞는 모둠 움직임과 전래·새 놀이 규칙을 만들어 놀며(5~8차시), 활동을 되돌아보아 음악과 맞은 장면과 어긋난 장면을 찾고, 고쳐 다시 하고, 친구 모둠 공연을 보며 근거를 들어 말하고, 박·리듬·빠르기·셈여림·가락 점검표를 들고 몸 악기로 다시 해 봅니다(9~12차시). 뒤의 열한 차시는 눈을 생활로 돌려, 집·학교·동네에서 들리는 음악과 함께 부르고 연주하는 장면을 찾아 기록하고 그 노래를 반이 함께 불러 봅니다(13~16차시). 이어서 학급 행사에 맞는 곡을 고르고 모두가 맡을 몫·차례·자리·준비물을 정해 리허설 뒤 작은 음악회로 실제로 참여합니다(17~20차시). 마지막에는 음악 생활 일지를 써서 내가 한 일을 남기고, 일지 그래프에서 적게 한 활동을 컵 리듬으로 해 본 뒤, 단원을 묶어 다음에 해 보고 싶은 음악 활동을 정합니다(21~23차시).","lessons":[{"n":1,"id":"g4-mus-1-01-01"},{"n":2,"id":"g4-mus-1-01-02"},{"n":3,"id":"g4-mus-1-01-03"},{"n":4,"id":"g4-mus-1-01-04"},{"n":5,"id":"g4-mus-1-01-05"},{"n":6,"id":"g4-mus-1-01-06"},{"n":7,"id":"g4-mus-1-01-07"},{"n":8,"id":"g4-mus-1-01-08"},{"n":9,"id":"g4-mus-1-01-09"},{"n":10,"id":"g4-mus-1-01-10"},{"n":11,"id":"g4-mus-1-01-11"},{"n":12,"id":"g4-mus-1-01-12"},{"n":13,"id":"g4-mus-1-01-13"},{"n":14,"id":"g4-mus-1-01-14"},{"n":15,"id":"g4-mus-1-01-15"},{"n":16,"id":"g4-mus-1-01-16"},{"n":17,"id":"g4-mus-1-01-17"},{"n":18,"id":"g4-mus-1-01-18"},{"n":19,"id":"g4-mus-1-01-19"},{"n":20,"id":"g4-mus-1-01-20"},{"n":21,"id":"g4-mus-1-01-21"},{"n":22,"id":"g4-mus-1-01-22"},{"n":23,"id":"g4-mus-1-01-23"}],"planned":23,"bundleSha256":"31c787d9e9b5044ed4bcd44a7776ac9e7d7c7f9fe9a893f7dcdf5bdfa3830dd7"},{"id":"g4-pe-2-03","catalogUnit":"g4-체육-2학기-3","grade":4,"subject":"체육","unitTitle":"3. 표현","flow":"1~10차시는 걷기·손뼉·발 구르기 같은 기본 움직임을 박과 센 박에 맞추는 데서 시작해, 빠르기 바꾸기·세마치장단·메아리 동작으로 넓히고, 어긋난 박을 스스로 찾아 고치며 모둠 발표로 마무리합니다. 11~19차시는 줄·천·훌라후프·리본 같은 도구가 만드는 모양과 안전 거리를 먼저 익히고, 도구와 몸짓을 8박 흐름으로 잇고 짝과 함께 표현한 뒤, 도구와 몸이 따로 논 곳을 찾아 다음 계획을 세웁니다. 20~28차시는 무용 영상·강강술래·자연 속 움직임을 보며 아름다움을 느낀 근거를 말하고, 마음에 든 동작을 내 방식으로 바꾸어 모둠 작품(처음·가운데·끝, 대형)을 만들어 감상하고 단원을 돌아봅니다. 교구는 계획·관찰·판단·기록을 맡고, 실제 움직임은 교사가 강당에서 관찰합니다.","lessons":[{"n":1,"id":"g4-pe-2-03-01"},{"n":2,"id":"g4-pe-2-03-02"},{"n":3,"id":"g4-pe-2-03-03"},{"n":4,"id":"g4-pe-2-03-04"},{"n":5,"id":"g4-pe-2-03-05"},{"n":6,"id":"g4-pe-2-03-06"},{"n":7,"id":"g4-pe-2-03-07"},{"n":8,"id":"g4-pe-2-03-08"},{"n":9,"id":"g4-pe-2-03-09"},{"n":10,"id":"g4-pe-2-03-10"},{"n":11,"id":"g4-pe-2-03-11"},{"n":12,"id":"g4-pe-2-03-12"},{"n":13,"id":"g4-pe-2-03-13"},{"n":14,"id":"g4-pe-2-03-14"},{"n":15,"id":"g4-pe-2-03-15"},{"n":16,"id":"g4-pe-2-03-16"},{"n":17,"id":"g4-pe-2-03-17"},{"n":18,"id":"g4-pe-2-03-18"},{"n":19,"id":"g4-pe-2-03-19"},{"n":20,"id":"g4-pe-2-03-20"},{"n":21,"id":"g4-pe-2-03-21"},{"n":22,"id":"g4-pe-2-03-22"},{"n":23,"id":"g4-pe-2-03-23"},{"n":24,"id":"g4-pe-2-03-24"},{"n":25,"id":"g4-pe-2-03-25"},{"n":26,"id":"g4-pe-2-03-26"},{"n":27,"id":"g4-pe-2-03-27"},{"n":28,"id":"g4-pe-2-03-28"}],"planned":28,"bundleSha256":"9fd7079a7fe4c23814814030c8ff2042988f44f6d010ffb8fcf7eacf8e142300"},{"id":"g4-soc-1-01","catalogUnit":"g4-사회-1학기-1","grade":4,"subject":"사회","unitTitle":"1. 지도로 만나는 우리 지역","flow":"앞 여덟 차시는 지도를 읽는 약속을 쌓습니다: 그림과 지도를 견주며 방위표·기호·범례·축척을 처음 만나고(1), 방위와 범례를 익힌 뒤(2), 축척으로 실제 거리를 구해 줄인 정도가 다른 두 지도를 견주고(3), 범례로 기호를 읽고(4), 영상지도와 일반 지도를 견줍니다(5). 6~8차시에는 그 약속으로 직접 길을 안내하고, 친구의 안내 글을 따라가 고치며, 걸음 수와 돌아간 방위표까지 써서 학교 안내문을 만듭니다. 9~10차시는 지어낸 가람도 지도에서 우리 시·군과 읍·면의 자리와 이웃 지역을 방위로 말하고, 11~13차시는 인구·넓이·기온 자료와 땅의 높낮이를 지도·그래프로 읽어 지역의 특징을 문장으로 옮깁니다. 14차시에 누리집·통계에서 자료를 찾아 출처를 적는 법을 익히고, 15차시에 다른 지역 친구에게 보낼 우리 지역 안내 카드로 단원을 묶어 스스로 점검합니다.","lessons":[{"n":1,"id":"g4-soc-1-01-01"},{"n":2,"id":"g4-social-map"},{"n":3,"id":"g4-soc-1-01-03"},{"n":4,"id":"g4-soc-1-01-04"},{"n":5,"id":"g4-soc-1-01-05"},{"n":6,"id":"g4-soc-1-01-06"},{"n":7,"id":"g4-soc-1-01-07"},{"n":8,"id":"g4-soc-1-01-08"},{"n":9,"id":"g4-soc-1-01-09"},{"n":10,"id":"g4-soc-1-01-10"},{"n":11,"id":"g4-soc-1-01-11"},{"n":12,"id":"g4-soc-1-01-12"},{"n":13,"id":"g4-soc-1-01-13"},{"n":14,"id":"g4-soc-1-01-14"},{"n":15,"id":"g4-soc-1-01-15"}],"planned":15,"bundleSha256":"f03845b29c8ef002c2465ecca2d2f0b202fe486339e1e8a0387e8002bda9f347"},{"id":"g5-eng-1-02","catalogUnit":"g5-영어-1학기-2","grade":5,"subject":"영어","unitTitle":"2. 읽기","flow":"1~3차시는 문장 리듬이다. 뜻을 담은 낱말(●)에 힘을 주고 짧은 도움 낱말(○)은 가볍게 붙이는 것부터 시작해, 대화문에서 짝의 강약을 짚어 주고, 긴 낱말의 강세와 묻는 말에 따라 강조할 낱말을 바꾸는 데까지 넓힌다. 4~6차시는 낱말을 어구 덩이로 묶어 한 덩이씩 읽으며, 친구의 쪽지와 초대장·길 안내처럼 새 글에서 덩이를 찾고 녹음을 들으며 잘못 끊은 덩이를 고친다. 7~9차시는 뜻이 이어지는 자리에 사선을 긋는다. 쉼표가 없는 곳에서도 끊을 수 있음을 알고, 세 문장 글에 사선을 그어 짝과 견주어 고친 뒤, 마지막 시간에 리듬·덩이·사선을 모두 살려 짧은 글을 낭독하고 스스로 평가한다. 단원 내내 \"빨리 읽기보다 강약과 덩이가 먼저\"라는 말을 되풀이한다.","lessons":[{"n":1,"id":"g5-eng-1-02-01"},{"n":2,"id":"g5-eng-1-02-02"},{"n":3,"id":"g5-eng-1-02-03"},{"n":4,"id":"g5-eng-1-02-04"},{"n":5,"id":"g5-eng-1-02-05"},{"n":6,"id":"g5-eng-1-02-06"},{"n":7,"id":"g5-eng-1-02-07"},{"n":8,"id":"g5-eng-1-02-08"},{"n":9,"id":"g5-eng-1-02-09"}],"planned":9,"bundleSha256":"d123c8a765003fbe40f5b4b6bc74fb402dadfb07a711dc14355080f415b7664d"},{"id":"g5-sci-1-01","catalogUnit":"g5-과학-1학기-1","grade":5,"subject":"과학","unitTitle":"1. 지층과 화석","flow":"1~4차시는 지층이다. 지층 사진에서 층을 세고 두께·색을 견준 뒤(1), 여러 곳의 지층을 견주어 평평한·휘어진·끊어진 지층을 가르고(2), 컵 모형으로 아래층이 먼저 쌓인다는 것을 그림·그래프로 나타내고(3), 지층 모형을 직접 만들어 실제 지층과 견준다(4). 5~8차시는 지층을 이루는 퇴적암을 알갱이 크기로 이암·사암·역암으로 나누고(5), 퇴적암이 만들어지는 과정을 모형과 견주며(6), 관찰을 표·그래프로 정리하고(7), 돋보기로 시료의 깨진 면을 관찰해 차례로 늘어놓는다(8). 9~12차시는 화석이 되는 조건과 만들어지는 과정을 알고(9), 화석으로 옛 환경을 추리하고(10), 그 과정과 추리를 네 컷·그래프로 나타낸 뒤(11), 화석 모형을 만들어 실제 화석과 견주며 단원을 정리한다(12).","lessons":[{"n":1,"id":"g5-sci-1-01-01"},{"n":2,"id":"g5-sci-1-01-02"},{"n":3,"id":"g5-sci-1-01-03"},{"n":4,"id":"g5-sci-1-01-04"},{"n":5,"id":"g5-sci-1-01-05"},{"n":6,"id":"g5-sci-1-01-06"},{"n":7,"id":"g5-sci-1-01-07"},{"n":8,"id":"g5-sci-1-01-08"},{"n":9,"id":"g5-sci-1-01-09"},{"n":10,"id":"g5-sci-1-01-10"},{"n":11,"id":"g5-sci-1-01-11"},{"n":12,"id":"g5-sci-1-01-12"}],"planned":12,"bundleSha256":"5205d04ce5ce3ecf99d0a1e571ce347f9657ac5200b62e9c44d99342abfbdb47"},{"id":"g6-prac-1-01","catalogUnit":"g6-실과-1학기-1","grade":6,"subject":"실과","unitTitle":"1. 인간 발달과 주도적 삶","flow":"1~4차시는 진로다: 둘레의 직업을 찾아 직업이 나와 사회에 하는 일을 나누고, 흥미·적성·성격을 묻는 물음으로 나를 알아본 뒤, 관심 직업 두 가지를 조사해 하는 일과 준비를 표로 정리하고 언제·무엇을·얼마나가 담긴 진로 계획서를 쓴다. 5~8차시는 옷이다: 옷의 기능을 보호·활동·표현으로 나누고, 운동장·과학실·행사장처럼 때와 장소에 맞는 옷차림을 고른 다음, 다음 날 일정에 맞춘 옷차림을 계획해 입어 보고 불편했던 점으로 계획을 고친다. 9~12차시는 가정일이다: 집안일을 끼니·옷·공간 갈래로 나누고 그 일이 멈추면 생기는 문제로 가치를 따진 뒤, 한 주 가정일 기록표와 그래프로 가족의 몫을 살펴 내가 더 맡을 일을 정해 실행한다. 세 묶음 모두 앞 차시에서 개념을 잡고 뒤 차시에서 내 생활에 옮기며, 마지막 차시에서 진로·옷·가정일을 '스스로 이끄는 삶'으로 묶어 자기 평가를 한다.","lessons":[{"n":1,"id":"g6-prac-1-01-01"},{"n":2,"id":"g6-prac-1-01-02"},{"n":3,"id":"g6-prac-1-01-03"},{"n":4,"id":"g6-prac-1-01-04"},{"n":5,"id":"g6-prac-1-01-05"},{"n":6,"id":"g6-prac-1-01-06"},{"n":7,"id":"g6-prac-1-01-07"},{"n":8,"id":"g6-prac-1-01-08"},{"n":9,"id":"g6-prac-1-01-09"},{"n":10,"id":"g6-prac-1-01-10"},{"n":11,"id":"g6-prac-1-01-11"},{"n":12,"id":"g6-prac-1-01-12"}],"planned":12,"bundleSha256":"d1f99ae4ed6ab3e2ca232e09f0af6b9c66db616952cca810ebd07c4dfb8c8bad"}];
